// run the script again, never here.
// The handoff: "Test this setup as a strategy" (SPEC § 11). It opens AlgoLift's Home chart with
// the copilot's box filled in; the person reads the request and sends it themselves.

import type { QueryInput } from './lang/query';
import { parseQuery } from './lang/query';
import { getPreset } from './presets';

export interface HandoffOptions {
  /** named in the request when given (e.g. 'ES') */
  instrument?: string;
  /** default 'https://www.algolift.ai' */
  base?: string;
  /** a tick size, needed only by a setup written in ticks */
  tickSize?: number;
}

export type HandoffRefusal = 'H_NO_CONDITION' | 'H_QUERY_ERROR';

export type HandoffResult =
  | { status: 'home'; request: string; url: string; message: string }
  | { status: 'refused'; code: HandoffRefusal; message: string };

export const HANDOFF_BASE = 'https://www.algolift.ai';
export const HANDOFF_MESSAGE = "Opens AlgoLift's Home chart with Algo ready to build this setup as a strategy. You review the request and send it.";
const LAST_LINE = 'Enter when the setup is known, and exit on the outcome or at the end of the session.';

export function buildHandoff(
  query: QueryInput | { preset: string; params?: Record<string, number> },
  options: HandoffOptions = {},
): HandoffResult {
  let qi: QueryInput;
  let presetId: string | undefined;
  let description: string | null = null;
  const iq = query as Partial<QueryInput> & { preset?: unknown; params?: Record<string, number> };
  if (typeof iq.setup === 'string' || typeof iq.outcome === 'string') {
    qi = query as QueryInput;
    if (typeof iq.preset === 'string') {
      presetId = iq.preset;
      const p = getPreset(iq.preset);
      // the plain words describe the preset only while its texts are the preset's own
      if (p && p.setup === qi.setup && p.outcome === qi.outcome) description = p.description;
    }
  } else {
    presetId = String(iq.preset);
    const p = getPreset(presetId);
    if (p) {
      qi = { setup: p.setup, outcome: p.outcome, params: iq.params };
      description = p.description;
    } else qi = { setup: 'all', outcome: 'touches 0' };
  }
  const parsed = parseQuery(qi, { preset: presetId, tickSize: options.tickSize });
  if (!parsed.ok) return { status: 'refused', code: 'H_QUERY_ERROR', message: parsed.errors[0].message };
  if (parsed.query.setup === 'all')
    return { status: 'refused', code: 'H_NO_CONDITION', message: 'Every session qualifies, so there is no setup to build a strategy from.' };
  const lines = [
    `Build a strategy from this Setup Odds setup${options.instrument ? ` on ${options.instrument}` : ''}.`,
    `Setup: ${parsed.query.setup}`,
    `Outcome: ${parsed.query.outcome}`,
  ];
  if (description !== null) lines.push(`In plain words: ${description}`);
  lines.push(LAST_LINE);
  const request = lines.join('\n');
  const base = (options.base ?? HANDOFF_BASE).replace(/\/+$/, '');
  return { status: 'home', request, url: `${base}/dashboard?ask=${encodeURIComponent(request)}`, message: HANDOFF_MESSAGE };
}
